MOD = 1_000_000_007


def count_decodings(s):
    prev2, prev1 = 0, 1
    for i, ch in enumerate(s):
        cur = 0
        if ch != "0":
            cur += prev1
        if i >= 1 and "10" <= s[i - 1:i + 1] <= "26":
            cur += prev2
        prev2, prev1 = prev1, cur % MOD
    return prev1
